// Shared source for the event registration narrative.
//
// Rendered by two builders, so the wording can never drift between them:
//   build-backend-doc.mjs        - as section 14 of the backend handbook
//   build-registration-doc.mjs   - as the standalone registration document
//
// Headings are not numbered here. Each builder applies its own numbering, and the
// anchor ids stay identical in both documents so cross-links keep working.

export const registrationIntro = "<p class=\"lead-sm\">\n          The single most involved journey in the system, and the one under active development. This\n          section covers every endpoint it touches, which service method each one calls, how the cart\n          holds stock, exactly how each payment method's total is built, and what runs on its own\n          afterwards.\n        </p>"

export const registrationSections = [
  {
    "id": "reg-map",
    "title": "The journey at a glance",
    "html": "\n\n        <div class=\"diagram\">\n          <svg viewBox=\"0 0 980 300\" role=\"img\" aria-label=\"Event registration flow from browsing to tickets\">\n            <defs>\n              <marker id=\"arrow\" markerWidth=\"9\" markerHeight=\"9\" refX=\"8\" refY=\"3\" orient=\"auto\">\n                <path d=\"M0,0 L0,6 L8,3 z\" fill=\"currentColor\" />\n              </marker>\n            </defs>\n            <g font-size=\"12\" font-family=\"system-ui, sans-serif\">\n              <rect x=\"8\" y=\"20\" width=\"150\" height=\"58\" rx=\"8\" class=\"box-read\" />\n              <text x=\"83\" y=\"43\" text-anchor=\"middle\" font-weight=\"600\">1. Browse</text>\n              <text x=\"83\" y=\"61\" text-anchor=\"middle\" class=\"muted\">register/bootstrap</text>\n\n              <rect x=\"186\" y=\"20\" width=\"150\" height=\"58\" rx=\"8\" class=\"box-write\" />\n              <text x=\"261\" y=\"43\" text-anchor=\"middle\" font-weight=\"600\">2. Create cart</text>\n              <text x=\"261\" y=\"61\" text-anchor=\"middle\" class=\"muted\">POST cart</text>\n\n              <rect x=\"364\" y=\"20\" width=\"150\" height=\"58\" rx=\"8\" class=\"box-write\" />\n              <text x=\"439\" y=\"43\" text-anchor=\"middle\" font-weight=\"600\">3. Add lines</text>\n              <text x=\"439\" y=\"61\" text-anchor=\"middle\" class=\"muted\">cart line only</text>\n\n              <rect x=\"542\" y=\"20\" width=\"150\" height=\"58\" rx=\"8\" class=\"box-write\" />\n              <text x=\"617\" y=\"43\" text-anchor=\"middle\" font-weight=\"600\">4. Attendees</text>\n              <text x=\"617\" y=\"61\" text-anchor=\"middle\" class=\"muted\">only if required</text>\n\n              <rect x=\"720\" y=\"20\" width=\"150\" height=\"58\" rx=\"8\" class=\"box-write\" />\n              <text x=\"795\" y=\"43\" text-anchor=\"middle\" font-weight=\"600\">5. Questionnaire</text>\n              <text x=\"795\" y=\"61\" text-anchor=\"middle\" class=\"muted\">only if authored</text>\n\n              <path d=\"M158,49 L182,49\" stroke=\"currentColor\" fill=\"none\" marker-end=\"url(#arrow)\" />\n              <path d=\"M336,49 L360,49\" stroke=\"currentColor\" fill=\"none\" marker-end=\"url(#arrow)\" />\n              <path d=\"M514,49 L538,49\" stroke=\"currentColor\" fill=\"none\" marker-end=\"url(#arrow)\" />\n              <path d=\"M692,49 L716,49\" stroke=\"currentColor\" fill=\"none\" marker-end=\"url(#arrow)\" />\n              <path d=\"M795,78 L795,110 L83,110 L83,142\" stroke=\"currentColor\" fill=\"none\" marker-end=\"url(#arrow)\" />\n\n              <rect x=\"8\" y=\"146\" width=\"150\" height=\"58\" rx=\"8\" class=\"box-write\" />\n              <text x=\"83\" y=\"169\" text-anchor=\"middle\" font-weight=\"600\">6. Price cart</text>\n              <text x=\"83\" y=\"187\" text-anchor=\"middle\" class=\"muted\">totals per method</text>\n\n              <rect x=\"186\" y=\"146\" width=\"150\" height=\"58\" rx=\"8\" class=\"box-money\" />\n              <text x=\"261\" y=\"169\" text-anchor=\"middle\" font-weight=\"600\">7. Pay</text>\n              <text x=\"261\" y=\"187\" text-anchor=\"middle\" class=\"muted\">intent / cheque / free</text>\n\n              <rect x=\"364\" y=\"146\" width=\"150\" height=\"58\" rx=\"8\" class=\"box-money\" />\n              <text x=\"439\" y=\"169\" text-anchor=\"middle\" font-weight=\"600\">8. Stripe webhook</text>\n              <text x=\"439\" y=\"187\" text-anchor=\"middle\" class=\"muted\">the real settlement</text>\n\n              <rect x=\"542\" y=\"146\" width=\"150\" height=\"58\" rx=\"8\" class=\"box-auto\" />\n              <text x=\"617\" y=\"169\" text-anchor=\"middle\" font-weight=\"600\">9. Tickets issued</text>\n              <text x=\"617\" y=\"187\" text-anchor=\"middle\" class=\"muted\">one per seat</text>\n\n              <rect x=\"720\" y=\"146\" width=\"150\" height=\"58\" rx=\"8\" class=\"box-auto\" />\n              <text x=\"795\" y=\"169\" text-anchor=\"middle\" font-weight=\"600\">10. Emails sent</text>\n              <text x=\"795\" y=\"187\" text-anchor=\"middle\" class=\"muted\">background jobs</text>\n\n              <path d=\"M158,175 L182,175\" stroke=\"currentColor\" fill=\"none\" marker-end=\"url(#arrow)\" />\n              <path d=\"M336,175 L360,175\" stroke=\"currentColor\" fill=\"none\" marker-end=\"url(#arrow)\" />\n              <path d=\"M514,175 L538,175\" stroke=\"currentColor\" fill=\"none\" marker-end=\"url(#arrow)\" />\n              <path d=\"M692,175 L716,175\" stroke=\"currentColor\" fill=\"none\" marker-end=\"url(#arrow)\" />\n\n              <rect x=\"186\" y=\"236\" width=\"330\" height=\"44\" rx=\"8\" class=\"box-read\" />\n              <text x=\"351\" y=\"263\" text-anchor=\"middle\">Confirmation page polls <tspan font-family=\"monospace\">GET /api/events/orders/{id}</tspan></text>\n              <path d=\"M617,204 L617,258 L520,258\" stroke=\"currentColor\" fill=\"none\" marker-end=\"url(#arrow)\" />\n\n              <g class=\"legend\" font-size=\"11\">\n                <rect x=\"600\" y=\"240\" width=\"12\" height=\"12\" rx=\"3\" class=\"box-read\" />\n                <text x=\"618\" y=\"250\">read</text>\n                <rect x=\"662\" y=\"240\" width=\"12\" height=\"12\" rx=\"3\" class=\"box-write\" />\n                <text x=\"680\" y=\"250\">write</text>\n                <rect x=\"724\" y=\"240\" width=\"12\" height=\"12\" rx=\"3\" class=\"box-money\" />\n                <text x=\"742\" y=\"250\">money</text>\n                <rect x=\"792\" y=\"240\" width=\"12\" height=\"12\" rx=\"3\" class=\"box-auto\" />\n                <text x=\"810\" y=\"250\">automatic</text>\n              </g>\n            </g>\n          </svg>\n        </div>\n\n        <div class=\"plain\">\n          Steps 4 and 5 appear only when the organizer configured them. Step 8 is the authority on\n          payment; step 7 only starts it. Steps 9 and 10 need no browser at all — close the tab after\n          paying and the tickets still arrive.\n        </div>"
  },
  {
    "id": "reg-endpoints",
    "title": "Every endpoint in the journey",
    "html": "\n        <p>\n          Grouped by the stage they belong to. Each row names the service method behind the route, so\n          you can go straight to the code.\n        </p>\n\n        <h4>Stage 1 — reading the event (nothing is created yet)</h4>\n        <div class=\"table-responsive\">\n          <table class=\"table table-sm table-bordered align-middle\">\n            <thead class=\"table-light\"><tr><th style=\"width:26rem\">Endpoint</th><th style=\"width:20rem\">Service method</th><th>Purpose</th></tr></thead>\n            <tbody>\n              <tr>\n                <td><span class=\"badge badge-method text-bg-primary\">GET</span> <code>/api/events/{id}/register</code></td>\n                <td><code>EventRegistrationService.GetEventRegistrationAsync</code></td>\n                <td>The whole registration page in one call — event details, sessions with ticket types, payment methods, which tabs to show. Heavy; prefer the bootstrap call below and load the rest per tab.</td>\n              </tr>\n              <tr>\n                <td><span class=\"badge badge-method text-bg-primary\">GET</span> <code>/api/events/{id}/register/bootstrap</code></td>\n                <td><code>GetEventRegistrationBootstrapAsync</code></td>\n                <td>The lightweight opener: branding, whether registration is open, the hold duration, and <code>visibleTabs</code>. Call this first.</td>\n              </tr>\n              <tr>\n                <td><span class=\"badge badge-method text-bg-primary\">GET</span> <code>/api/events/{id}/register/description</code></td>\n                <td><code>GetEventRegistrationDescriptionAsync</code></td>\n                <td>Just the long description and summary, for the description tab.</td>\n              </tr>\n              <tr>\n                <td><span class=\"badge badge-method text-bg-primary\">GET</span> <code>/api/events/{id}/register/sessions</code></td>\n                <td><code>GetEventRegistrationSessionsAsync</code></td>\n                <td>Sessions with their ticket types and prices — what the buyer picks from.</td>\n              </tr>\n              <tr>\n                <td><span class=\"badge badge-method text-bg-primary\">GET</span> <code>/api/events/{id}/register/attendee-info</code></td>\n                <td><code>GetEventRegistrationAttendeeInfoAsync</code></td>\n                <td>Returns <em>only</em> the sessions whose <code>RequiresAttendeeInfo</code> flag is set, so the page knows which lines need per-seat names.</td>\n              </tr>\n              <tr>\n                <td><span class=\"badge badge-method text-bg-primary\">GET</span> <code>/api/events/{id}/register/questionnaire</code></td>\n                <td><code>GetEventRegistrationQuestionnaireAsync</code></td>\n                <td>The organizer's custom forms and questions for this event, as field definitions to render.</td>\n              </tr>\n              <tr>\n                <td><span class=\"badge badge-method text-bg-primary\">GET</span> <code>/api/events/tickets/{e}/{s}/{t}/availability</code></td>\n                <td><code>TicketingService.GetAvailabilityAsync</code></td>\n                <td>Live remaining count for one ticket type. Read-only — it holds nothing.</td>\n              </tr>\n            </tbody>\n          </table>\n        </div>\n\n        <h4>Stage 2 — the cart</h4>\n        <div class=\"table-responsive\">\n          <table class=\"table table-sm table-bordered align-middle\">\n            <thead class=\"table-light\"><tr><th style=\"width:26rem\">Endpoint</th><th style=\"width:20rem\">Service method</th><th>Purpose</th></tr></thead>\n            <tbody>\n              <tr>\n                <td><span class=\"badge badge-method text-bg-success\">POST</span> <code>/api/events/cart</code> <span class=\"badge text-bg-light border flag\">BotMitigation</span></td>\n                <td><code>EventCartService.CreateCartAsync</code></td>\n                <td>Creates only the event-module cart: an <code>EventInvoice</code> with <code>CartStatus = Open</code>, buyer identity snapshot, subtotal/total set to zero, and one fixed expiry for the whole cart. No shared <code>Invoice</code> row exists yet.</td>\n              </tr>\n              <tr>\n                <td><span class=\"badge badge-method text-bg-primary\">GET</span> <code>/api/events/cart/{cartId}</code></td>\n                <td><code>EventCartService.GetCartAsync</code></td>\n                <td>Reads the cart back — lines, subtotal, and when the hold expires. Safe to poll after a page refresh.</td>\n              </tr>\n              <tr>\n                <td><span class=\"badge badge-method text-bg-success\">POST</span> <code>/api/events/cart/{cartId}/lines</code></td>\n                <td><code>EventCartService.AddLineAsync</code></td>\n                <td>Validates sale window, quantity and current availability, resolves the price period, then writes an <code>EventInvoiceItem</code> and an Active <code>TicketReservation</code> tied to the cart expiry. It does <strong>not</strong> lock or consume inventory; the real claim happens when payment starts.</td>\n              </tr>\n              <tr>\n                <td><span class=\"badge badge-method text-bg-danger\">DELETE</span> <code>/api/events/cart/{cartId}/lines/{lineId}</code></td>\n                <td><code>EventCartService.RemoveLineAsync</code></td>\n                <td>Soft-deletes the line, cancels its reservation and refreshes the ticket-type counters so the seats are immediately back on sale.</td>\n              </tr>\n              <tr>\n                <td><span class=\"badge badge-method text-bg-success\">POST</span> <code>/api/events/cart/{cartId}/lines/{lineId}/attendees</code></td>\n                <td><code>EventCartAttendeeService.SubmitAttendeesAsync</code></td>\n                <td>Names the people in one line's seats. The count must equal the line quantity exactly, and every attendee needs a name. Replaces any previous submission for that line.</td>\n              </tr>\n              <tr>\n                <td><span class=\"badge badge-method text-bg-success\">POST</span> <code>/api/events/cart/{cartId}/answers</code></td>\n                <td><code>EventCartAnswerService.SubmitAnswersAsync</code></td>\n                <td>All questionnaire answers for the order in one call. Validates every answer against its field definition, then writes the <code>EventPurchaseSubmission</code> tree. Re-submittable — it updates in place rather than duplicating.</td>\n              </tr>\n              <tr>\n                <td><span class=\"badge badge-method text-bg-success\">POST</span> <code>/api/events/cart/{cartId}/answers/files</code> <span class=\"badge text-bg-light border flag\">BotMitigation · 12 MB</span></td>\n                <td><code>EventCartAnswerService.UploadAnswerFileAsync</code></td>\n                <td>Stores one attachment and returns its <code>fileStorageId</code>, which the answers call then references. Also records the upload as in-flight so an abandoned one can be collected later.</td>\n              </tr>\n              <tr>\n                <td><span class=\"badge badge-method text-bg-success\">POST</span> <code>/api/events/cart/{cartId}/price</code></td>\n                <td><code>EventCartPricingService.PriceCartAsync</code></td>\n                <td>Prices the whole cart and returns a separate total per payment method. Also the coupon entry point. Covered in detail in <a href=\"#reg-pricing\">the pricing section</a>.</td>\n              </tr>\n            </tbody>\n          </table>\n        </div>\n\n        <h4>Stage 3 — payment</h4>\n        <div class=\"table-responsive\">\n          <table class=\"table table-sm table-bordered align-middle\">\n            <thead class=\"table-light\"><tr><th style=\"width:26rem\">Endpoint</th><th style=\"width:20rem\">Service method</th><th>Purpose</th></tr></thead>\n            <tbody>\n              <tr>\n                <td><span class=\"badge badge-method text-bg-primary\">GET</span> <code>/api/public/stripe/{accountId}/credentials</code></td>\n                <td><code>StripeService.GetPublicCredentialsAsync</code></td>\n                <td>The publishable key the browser needs to mount Stripe's card fields, before any payment exists.</td>\n              </tr>\n              <tr>\n                <td><span class=\"badge badge-method text-bg-success\">POST</span> <code>/api/events/cart/{cartId}/checkout/intent</code> <span class=\"badge text-bg-light border flag\">BotMitigation</span></td>\n                <td><code>EventCheckoutService.CreatePaymentIntentAsync</code></td>\n                <td>First claims the seats under ticket-type locks. If the buyer won, it raises the shared <code>Invoice</code>, mirrors cart lines to <code>InvoiceItem</code>, recomputes charges for the chosen method, creates the Stripe intent, and records a <code>Pending</code> <code>InvoicePayment</code>. Returns the client secret.</td>\n              </tr>\n              <tr>\n                <td><span class=\"badge badge-method text-bg-success\">POST</span> <code>/api/events/cart/{cartId}/checkout/cheque</code> <span class=\"badge text-bg-light border\">Signed in</span></td>\n                <td><code>EventCheckoutService.RecordChequePaymentAsync</code></td>\n                <td>Organizer-only, and refused unless the caller's organizer owns the event. Claims seats first, raises the invoice, records a pending cheque with no processor fee, and then <strong>issues the tickets immediately</strong> while the invoice stays owing.</td>\n              </tr>\n              <tr>\n                <td><span class=\"badge badge-method text-bg-success\">POST</span> <code>/api/events/cart/{cartId}/checkout/confirm</code></td>\n                <td><code>EventCheckoutService.ConfirmCheckoutAsync</code></td>\n                <td>The fast path the browser calls after paying, and the <em>only</em> path for a zero-total order. It settles open attempts, reads whether issuance is authorised, and runs the same idempotent issuance the webhook runs. For free orders, this is where seats are claimed.</td>\n              </tr>\n              <tr>\n                <td><span class=\"badge badge-method text-bg-success\">POST</span> <code>/api/public/stripe/web-hook</code></td>\n                <td><code>StripeService.HandleWebHookAsync</code> → <code>EventPaymentSettlementService.HandlePaymentSucceededAsync</code></td>\n                <td><strong>The authority.</strong> Verifies Stripe's signature, settles the invoice, then routes to the owning module using the intent's metadata. Covered in <a href=\"#reg-settlement\">the settlement section</a>.</td>\n              </tr>\n              <tr>\n                <td><span class=\"badge badge-method text-bg-primary\">GET</span> <code>/api/events/revenue-plans/applicable</code></td>\n                <td><code>RevenuePlanResolverService.GetApplicableRevenueChargesAsync</code></td>\n                <td>The platform's charges for an organizer. The pricing service calls the same method internally; this route exists so a page can show them before a cart exists.</td>\n              </tr>\n            </tbody>\n          </table>\n        </div>\n\n        <h4>Stage 4 — after the sale</h4>\n        <div class=\"table-responsive\">\n          <table class=\"table table-sm table-bordered align-middle\">\n            <thead class=\"table-light\"><tr><th style=\"width:26rem\">Endpoint</th><th style=\"width:20rem\">Service method</th><th>Purpose</th></tr></thead>\n            <tbody>\n              <tr>\n                <td><span class=\"badge badge-method text-bg-primary\">GET</span> <code>/api/events/orders/{orderId}</code> <span class=\"badge text-bg-light border flag\">public-poll</span></td>\n                <td><code>EventOrderStatusService.GetOrderStatusAsync</code></td>\n                <td>The confirmation page. A pure projection — issues nothing, changes nothing. Returns <code>Confirmed</code>, <code>Processing</code> or <code>Failed</code> plus <code>pollAfterSeconds</code>, which reaches zero when the order is terminal. Rate-limited to 60 per minute per IP.</td>\n              </tr>\n              <tr>\n                <td><span class=\"badge badge-method text-bg-primary\">GET</span> <code>/api/events/tickets/{ticketId}/view</code></td>\n                <td><code>EventTicketViewService.GetTicketViewAsync</code></td>\n                <td>One ticket rendered for the attendee. Anonymous, guarded only by the unguessable id.</td>\n              </tr>\n              <tr>\n                <td><span class=\"badge badge-method text-bg-primary\">GET</span> <code>/api/organizer/events/invoices/list</code></td>\n                <td><code>EventInvoiceService.GetEventInvoiceListAsync</code></td>\n                <td>The organizer's list of orders for their events.</td>\n              </tr>\n              <tr>\n                <td><span class=\"badge badge-method text-bg-primary\">GET</span> <code>/api/organizer/events/invoices/{invoiceId}</code></td>\n                <td><code>EventInvoiceService.GetEventInvoiceDetailAsync</code></td>\n                <td>One order in full — lines, charges, payments, tickets, answers.</td>\n              </tr>\n              <tr>\n                <td><span class=\"badge badge-method text-bg-success\">POST</span> <code>/api/organizer/events/invoices/{invoiceId}/resend</code></td>\n                <td><code>EventInvoiceService.ResendInvoiceAsync</code></td>\n                <td>Re-sends the whole order's confirmation and tickets. Use this when delivery failed — a failed email is never a reason to refund.</td>\n              </tr>\n              <tr>\n                <td><span class=\"badge badge-method text-bg-success\">POST</span> <code>/api/organizer/events/invoices/{invoiceId}/tickets/{ticketId}/resend</code></td>\n                <td><code>EventInvoiceService.ResendTicketAsync</code></td>\n                <td>Re-sends one ticket only.</td>\n              </tr>\n              <tr>\n                <td><span class=\"badge badge-method text-bg-success\">POST</span> <code>/api/organizer/events/tickets/check-in</code></td>\n                <td><code>TicketingService.CheckInAsync</code></td>\n                <td>Scans a ticket code at the door and writes a <code>TicketCheckInLog</code> row. Refuses a code that is already used, cancelled or refunded.</td>\n              </tr>\n            </tbody>\n          </table>\n        </div>\n\n        <div class=\"dont\">\n          <code>EventTicketSalesController</code> — <code>POST /api/events/tickets/reservations</code>,\n          <code>/checkout/invoice</code> and <code>/checkout/confirm</code> — is the earlier,\n          single-line purchase path that predates the cart. It still compiles and still works, but new\n          work belongs on the cart endpoints above. Do not mix the two in one journey.\n          <code>GET /api/events/{id}/register/payment</code> is superseded the same way: it takes a\n          subtotal from the caller, whereas <code>POST /cart/{id}/price</code> derives it from the\n          server-owned cart. Never trust a total the browser supplies.\n        </div>"
  },
  {
    "id": "reg-cart",
    "title": "How the cart actually works",
    "html": "\n        <p>\n          The cart now lives in the event module before money exists. An <code>EventInvoice</code> is the cart, <code>EventInvoiceItem</code> rows are the lines, and <code>TicketReservation</code> rows remember what the buyer selected. A shared <code>Invoice</code> is raised only when checkout starts, because an abandoned cart is not an order. The important rows are:\n        </p>\n\n        <div class=\"diagram\">\n          <svg viewBox=\"0 0 900 340\" role=\"img\" aria-label=\"Rows created when a cart line is added\">\n            <g font-size=\"12\" font-family=\"system-ui, sans-serif\">\n              <rect x=\"20\" y=\"16\" width=\"240\" height=\"86\" rx=\"8\" class=\"box-write\" />\n              <text x=\"140\" y=\"40\" text-anchor=\"middle\" font-weight=\"600\">EventInvoice</text>\n              <text x=\"140\" y=\"58\" text-anchor=\"middle\" class=\"muted\">CartStatus = Open</text>\n              <text x=\"140\" y=\"74\" text-anchor=\"middle\" class=\"muted\">buyer snapshot, expiry</text>\n              <text x=\"140\" y=\"90\" text-anchor=\"middle\" class=\"muted\">uniqueId = the cart id</text>\n\n              <rect x=\"330\" y=\"16\" width=\"240\" height=\"86\" rx=\"8\" class=\"box-read\" />\n              <text x=\"450\" y=\"40\" text-anchor=\"middle\" font-weight=\"600\">Shared Invoice</text>\n              <text x=\"450\" y=\"58\" text-anchor=\"middle\" class=\"muted\">created at checkout</text>\n              <text x=\"450\" y=\"74\" text-anchor=\"middle\" class=\"muted\">status = PendingPayment</text>\n              <text x=\"450\" y=\"90\" text-anchor=\"middle\" class=\"muted\">order number minted here</text>\n\n              <rect x=\"640\" y=\"16\" width=\"240\" height=\"86\" rx=\"8\" class=\"box-read\" />\n              <text x=\"760\" y=\"40\" text-anchor=\"middle\" font-weight=\"600\">EventPurchaseSubmission</text>\n              <text x=\"760\" y=\"58\" text-anchor=\"middle\" class=\"muted\">questionnaire answers</text>\n              <text x=\"760\" y=\"74\" text-anchor=\"middle\" class=\"muted\">one per order</text>\n              <text x=\"760\" y=\"90\" text-anchor=\"middle\" class=\"muted\">created on first submit</text>\n\n              <path d=\"M260,59 L326,59\" stroke=\"currentColor\" fill=\"none\" marker-end=\"url(#arrow)\" />\n              <path d=\"M570,59 L636,59\" stroke=\"currentColor\" fill=\"none\" marker-end=\"url(#arrow)\" />\n\n              <path d=\"M140,102 L140,140\" stroke=\"currentColor\" fill=\"none\" marker-end=\"url(#arrow)\" />\n\n              <rect x=\"20\" y=\"144\" width=\"240\" height=\"76\" rx=\"8\" class=\"box-write\" />\n              <text x=\"140\" y=\"168\" text-anchor=\"middle\" font-weight=\"600\">InvoiceItem</text>\n              <text x=\"140\" y=\"186\" text-anchor=\"middle\" class=\"muted\">mirrored at checkout</text>\n              <text x=\"140\" y=\"202\" text-anchor=\"middle\" class=\"muted\">soft-deleted if line removed</text>\n\n              <rect x=\"330\" y=\"144\" width=\"240\" height=\"76\" rx=\"8\" class=\"box-write\" />\n              <text x=\"450\" y=\"168\" text-anchor=\"middle\" font-weight=\"600\">EventInvoiceItem</text>\n              <text x=\"450\" y=\"186\" text-anchor=\"middle\" class=\"muted\">session, ticket type</text>\n              <text x=\"450\" y=\"202\" text-anchor=\"middle\" class=\"muted\">price period</text>\n\n              <rect x=\"640\" y=\"144\" width=\"240\" height=\"76\" rx=\"8\" class=\"box-money\" />\n              <text x=\"760\" y=\"168\" text-anchor=\"middle\" font-weight=\"600\">TicketReservation</text>\n              <text x=\"760\" y=\"186\" text-anchor=\"middle\" class=\"muted\">Active, cart-scoped</text>\n              <text x=\"760\" y=\"202\" text-anchor=\"middle\" class=\"muted\">consumes only after pay starts</text>\n\n              <path d=\"M260,182 L326,182\" stroke=\"currentColor\" fill=\"none\" marker-end=\"url(#arrow)\" />\n              <path d=\"M570,182 L636,182\" stroke=\"currentColor\" fill=\"none\" marker-end=\"url(#arrow)\" />\n\n              <path d=\"M760,220 L760,258\" stroke=\"currentColor\" fill=\"none\" marker-end=\"url(#arrow)\" />\n              <rect x=\"640\" y=\"262\" width=\"240\" height=\"60\" rx=\"8\" class=\"box-auto\" />\n              <text x=\"760\" y=\"286\" text-anchor=\"middle\" font-weight=\"600\">EventTicket</text>\n              <text x=\"760\" y=\"304\" text-anchor=\"middle\" class=\"muted\">only after payment settles</text>\n\n              <rect x=\"330\" y=\"262\" width=\"240\" height=\"60\" rx=\"8\" class=\"box-write\" />\n              <text x=\"450\" y=\"286\" text-anchor=\"middle\" font-weight=\"600\">EventInvoiceItemAttendee</text>\n              <text x=\"450\" y=\"304\" text-anchor=\"middle\" class=\"muted\">one per seat, pre-payment</text>\n              <path d=\"M450,220 L450,258\" stroke=\"currentColor\" fill=\"none\" marker-end=\"url(#arrow)\" />\n              <path d=\"M570,292 L636,292\" stroke=\"currentColor\" fill=\"none\" marker-end=\"url(#arrow)\" />\n            </g>\n          </svg>\n        </div>\n\n        <h4>Why EventInvoice comes before Invoice</h4>\n        <p>\n          The shared <code>Invoice</code> table is used by Donation and Membership too, so the cart no longer writes there while a buyer is only browsing. <code>RaiseInvoiceAsync</code> creates the shared invoice at payment start, links it back to the <code>EventInvoice</code>, mirrors live cart lines to <code>InvoiceItem</code>, and marks the cart <code>Converted</code>.\n        </p>\n\n        <h4>The hold clock</h4>\n        <div class=\"table-responsive\">\n          <table class=\"table table-sm table-bordered\">\n            <tbody>\n              <tr><th style=\"width:16rem\">How long</th><td><code>Event.PurchaseTimeLimit</code> if the organizer set one, otherwise <code>AppSettings.PurchaseTimeLimitMinutes</code>, otherwise a built-in default. Resolved by <code>TicketingShared.GetEffectiveHoldMinutes</code>.</td></tr>\n              <tr><th>Counted from</th><td>The <em>cart's</em> creation time, not the line's. Every line shares one deadline, so adding a line late does not extend an already-aging cart.</td></tr>\n              <tr><th>Who enforces it</th><td><code>EventCartMaintenanceHostedService</code>, every minute. It marks expired open carts <code>Abandoned</code>. <code>TicketingService.ExpireStaleReservationsAsync</code> owns reservation expiry and counter refresh, so the two background passes do not fight over stock.</td></tr>\n              <tr><th>What the buyer sees</th><td><code>expiresAtUtc</code> on the cart response. Once it passes, pricing refuses the line with \"the hold has expired; remove and re-add this line\".</td></tr>\n            </tbody>\n          </table>\n        </div>\n\n        <h4 id=\"reg-cart-capability\">Who is allowed to touch a cart</h4>\n        <p>\n          A cart is anonymous — there is no principal to check, no <code>[Authorize]</code> to lean on — so\n          for a while the cart's <code>uniqueId</code> was the only thing standing between a stranger and\n          somebody else's attendee names, email addresses and prices. A secret URL is not authorisation.\n          Ids leak in ordinary, non-malicious use:\n        </p>\n        <div class=\"table-responsive\">\n          <table class=\"table table-sm table-bordered\">\n            <thead class=\"table-light\"><tr><th style=\"width:34%\">How the id escapes</th><th>What an unguarded route would have granted</th></tr></thead>\n            <tbody>\n              <tr>\n                <td>Buyer pastes the wizard URL into a support ticket; an agent screenshots it.</td>\n                <td><code>GET /api/events/cart/{id}</code> returns every attendee's full name, email, phone and the amounts — to anyone who reads the ticket.</td>\n              </tr>\n              <tr>\n                <td>The URL reaches request logs, an APM trace, an analytics pipeline, or a referrer header on a third-party asset.</td>\n                <td>Anybody with log or dashboard access — vendors included — could replay the cart, mutate its lines, or drive <code>/checkout/intent</code>.</td>\n              </tr>\n              <tr>\n                <td>A shared or kiosk machine keeps the id in browser history.</td>\n                <td>The next person resumes a stranger's registration and pays with the previous buyer's attendee data attached.</td>\n              </tr>\n              <tr>\n                <td>An attacker harvests ids from any of the above and scripts them.</td>\n                <td>Bulk extraction of buyer and attendee personal data across an organizer's entire event — a reportable breach, not an inconvenience.</td>\n              </tr>\n            </tbody>\n          </table>\n        </div>\n        <div class=\"plain\">\n          The id still <em>identifies</em> the cart. It no longer <em>authorises</em> anything. The signed\n          cookie does, and a browser only ever returns a cookie to the origin that set it — so a copied\n          URL is inert wherever it lands.\n        </div>\n        <p>\n          <code>POST /api/events/cart</code> issues a signed capability as an http-only cookie, and\n          <code>RequireCartCapabilityAttribute</code> refuses every later cart-scoped and checkout-scoped\n          call without it. The cheque route is organizer-authenticated and is deliberately not gated on a\n          buyer's cookie.\n        </p>\n        <div class=\"table-responsive\">\n          <table class=\"table table-sm table-bordered\">\n            <tbody>\n              <tr><th style=\"width:16rem\">Token</th><td><code>{cartUniqueId:N}.{expiryUnix}.{base64url-signature}</code>, signed HMAC-SHA256 and compared with <code>CryptographicOperations.FixedTimeEquals</code>.</td></tr>\n              <tr><th>Cookie</th><td><code>IdealiEventCart_{cartUniqueId:N}</code> — <code>HttpOnly</code>, <code>Secure</code>, <code>SameSite=Strict</code>, path-scoped to <code>/api/events/cart</code> so a capability never rides along on an unrelated API call or into a log of one. One cookie per cart, so two carts open in one browser do not evict each other.</td></tr>\n              <tr><th>Binding</th><td>The token carries its own cart id, so renaming a valid cookie onto another cart fails the signature check.</td></tr>\n              <tr><th>Lifetime</th><td>Cart expiry plus a 60-minute grace. A card authorised just after the hold lapsed must still be confirmable.</td></tr>\n              <tr><th>Verification</th><td>Stateless. Nothing is stored server-side — no session table, no Redis. The signing key is the only shared state, which is why every instance in one environment must carry the identical key.</td></tr>\n              <tr><th>Refusal</th><td>One <code>403</code> with <code>errorCode: \"cart_capability_required\"</code> and one message for every case — no cookie, wrong cart, expired, forged, cart that never existed — so the endpoint cannot be used to enumerate carts.</td></tr>\n            </tbody>\n          </table>\n        </div>\n\n        <div class=\"must\">\n          <p class=\"mb-2\">\n            <strong><code>EventCartCapability:SigningKey</code> must exist before the API can start.</strong>\n            It throws on a missing or under-32-byte value on purpose: a default fallback key is a known key,\n            and a known key lets anyone mint a valid capability for any cart — worse than no gate at all,\n            because it looks guarded.\n          </p>\n<pre class=\"mb-2\"><code># Windows PowerShell 5.1 — 48 random bytes, base64\n$b = New-Object byte[] 48; ([System.Security.Cryptography.RNGCryptoServiceProvider]::new()).GetBytes($b); [Convert]::ToBase64String($b)</code></pre>\n<pre class=\"mb-2\"><code>// Configuration/secrets.json — gitignored, never commit a real value\n\"EventCartCapability\": { \"SigningKey\": \"&lt;generated value&gt;\" }</code></pre>\n          <p class=\"mb-0\">\n            One value per environment — local, staging and production each get their own, because the key\n            mints valid tokens for every cart and staging is always the weakest of the three. Identical\n            across every instance <em>within</em> one environment. Staging and production keys are generated\n            inside the secret store itself and pasted nowhere else. The generation command also lives in\n            <code>docs/README.md</code> in the API repository.\n          </p>\n        </div>\n\n        <p>What breaks without it, and how each failure presents:</p>\n        <div class=\"table-responsive\">\n          <table class=\"table table-sm table-bordered\">\n            <thead class=\"table-light\"><tr><th style=\"width:30%\">Situation</th><th>Symptom</th></tr></thead>\n            <tbody>\n              <tr><td>Key missing or too short</td><td>The process throws at startup with the setting name in the message. The API does not serve traffic — deliberately, rather than serving registration ungated.</td></tr>\n              <tr><td>Two instances behind one load balancer hold different keys</td><td>Instance A sets a cookie, the next request lands on B, and B reads it as forged. Intermittent <code>403</code>s that look like session loss and never reproduce locally.</td></tr>\n              <tr><td>Key rotated during trading hours</td><td>Every in-flight cart dies at once. Existing cookies stop verifying and those buyers are refused mid-registration, some already at the payment step. Rotate in a low-traffic window.</td></tr>\n              <tr><td>Frontend client omits <code>withCredentials: true</code></td><td>Cart creation returns <code>200</code>, then every following cart call returns <code>403 cart_capability_required</code>. Nothing is wrong server-side; the browser was never asked to send the cookie.</td></tr>\n              <tr><td>SPA and API are not same-site, or not on HTTPS</td><td><code>SameSite=Strict</code> and <code>Secure</code> mean the browser withholds the cookie regardless of client configuration. Same symptom as above, different cause.</td></tr>\n            </tbody>\n          </table>\n        </div>\n        <h4>What the frontend does with a refusal</h4>\n        <p>\n          A refused capability is terminal. The cart cannot be repaired from the browser — the cookie is\n          http-only, the server will refuse every later call on that cart identically, and it will not say\n          which of the five causes applied. So the wizard does not retry and does not surface the raw\n          failure inline.\n        </p>\n        <div class=\"table-responsive\">\n          <table class=\"table table-sm table-bordered\">\n            <tbody>\n              <tr><th style=\"width:16rem\">Detection</th><td><code>isCartSessionLostError</code> in <code>src/utils/errors.ts</code>. Matches <code>403</code> plus <code>cart_capability_required</code>. The failure envelope arrives PascalCase and never passes through <code>camelizeKeys</code>, so both spellings of the error-code field are read.</td></tr>\n              <tr><th>Reaction</th><td><code>useRegistrationCart</code> drops the cart id, coupon, buyer identity, any buffered line changes and the stored cart id, then raises <code>isSessionLost</code>. Keeping the cart would leave the buyer retrying against one the server will never accept again.</td></tr>\n              <tr><th>What the buyer sees</th><td>A single-action \"Registration session ended\" dialog. The only button reloads the form. There is no retry, because nothing can be retried.</td></tr>\n              <tr><th>Wording</th><td>Fixed client-side, not read from the response. The server's message is deliberately identical for every cause, so echoing it adds nothing and couples the copy to the API.</td></tr>\n              <tr><th>Not this path</th><td>Restoring a cart id from storage on page load. That failure clears the stored id silently and shows a clean form — a returning buyer with a dead cookie has done nothing wrong and should not meet an error.</td></tr>\n              <tr><th>Any other failure</th><td>Left alone. A <code>500</code> or a rejected coupon keeps the cart intact and retryable.</td></tr>\n            </tbody>\n          </table>\n        </div>\n\n        <div class=\"dont\">\n          Adding a new anonymous cart-scoped action without <code>[RequireCartCapability]</code>. It reopens\n          the entire hole above, and only the reflection test in <code>RequireCartCapabilityAttributeTests</code>\n          will notice — nothing else in the build will.\n        </div>\n\n        <h4>Two gates you will meet everywhere</h4>\n        <div class=\"table-responsive\">\n          <table class=\"table table-sm table-bordered\">\n            <tbody>\n              <tr>\n                <th style=\"width:16rem\"><code>EnsureCartOpen</code></th>\n                <td>Used before <em>editing</em>. Refuses if the invoice is not <code>PendingPayment</code>, or if any payment already succeeded.</td>\n              </tr>\n              <tr>\n                <th><code>EnsureCartPayable</code></th>\n                <td>Used before <em>paying</em>. Only checks the status — a live attempt does not block replacing it, because a buyer who abandoned Stripe's dialog cannot cancel it themselves.</td>\n              </tr>\n            </tbody>\n          </table>\n        </div>\n        <p>\n          Every editing call also runs <code>EventPaymentAttempts.ReleaseAbandonedAttemptsAsync</code>\n          first, which voids a stale Stripe attempt so the buyer is not locked out of their own cart.\n        </p>\n\n        <h4>Where oversell is prevented</h4>\n        <p>\n          Browsing cart lines are intentionally lightweight: they validate against current availability, but they do not queue every buyer behind the ticket type and they do not make the event look sold out. The real inventory claim happens in <code>EventCheckoutService.ClaimSeatsForPaymentAsync</code>, called by <code>/checkout/intent</code>, <code>/checkout/cheque</code>, and by <code>/checkout/confirm</code> for free orders.\n        </p>\n        <ol class=\"step-rail\">\n          <li><strong>Apply a short SQL lock wait.</strong> <code>SET LOCK_TIMEOUT 3000</code> keeps a rush from tying up request threads and pooled connections for the full command timeout.</li>\n          <li><strong>Lock ticket types in sorted order.</strong> Each distinct ticket type is read with <code>UPDLOCK, HOLDLOCK</code>, so two buyers cannot both read the same last seat as available, and multi-ticket carts avoid lock-order deadlocks.</li>\n          <li><strong>Re-read availability inside the same transaction.</strong> The winner stamps <code>PaymentStartedUtc</code> and extends the hold into payment grace. Losers get a truthful sold-out or reduced-quantity message and no payment intent.</li>\n          <li><strong>Raise money only after the claim.</strong> The shared <code>Invoice</code>, charge rows and payment attempt are created only for carts whose seats survived the claim.</li>\n        </ol>\n        <div class=\"rule\">\n          The guarantee is no oversell and no half-charged loser. A buyer can still lose the race, hit the 3-second contention cap, or be asked to retry; that is expected behaviour under load, not a blocker or a server failure.\n        </div>\n\n        <div class=\"dont\">\n          Adding or removing a line calls <code>TicketingShared.ResetPricingAsync</code>, which throws\n          away the previously calculated charge lines. Any total the frontend is holding becomes stale\n          the moment the cart changes. Always call <code>/price</code> again before showing a total.\n        </div>",
    "subs": [
      {
        "id": "reg-cart-capability",
        "title": "Who is allowed to touch a cart"
      }
    ]
  },
  {
    "id": "reg-pricing",
    "title": "How the total is calculated",
    "html": "\n        <p>\n          This is the part people get wrong most often, so follow the order exactly. It is applied by\n          <code>EventCartPricingService.PriceCartAsync</code> and the arithmetic lives in\n          <code>BuyerChargeCalculator</code>.\n        </p>\n\n        <div class=\"diagram\">\n          <svg viewBox=\"0 0 900 430\" role=\"img\" aria-label=\"How an event order total is built up\">\n            <g font-size=\"12\" font-family=\"system-ui, sans-serif\">\n              <rect x=\"40\" y=\"14\" width=\"500\" height=\"44\" rx=\"8\" class=\"box-read\" />\n              <text x=\"60\" y=\"41\" font-weight=\"600\">Subtotal</text>\n              <text x=\"530\" y=\"41\" text-anchor=\"end\" class=\"muted\">sum of unitPrice x quantity for every line</text>\n\n              <path d=\"M290,58 L290,76\" stroke=\"currentColor\" fill=\"none\" marker-end=\"url(#arrow)\" />\n              <rect x=\"40\" y=\"80\" width=\"500\" height=\"44\" rx=\"8\" class=\"box-write\" />\n              <text x=\"60\" y=\"107\" font-weight=\"600\">− Membership discount</text>\n              <text x=\"530\" y=\"107\" text-anchor=\"end\" class=\"muted\">per line, if the signed-in member's type qualifies</text>\n\n              <path d=\"M290,124 L290,142\" stroke=\"currentColor\" fill=\"none\" marker-end=\"url(#arrow)\" />\n              <rect x=\"40\" y=\"146\" width=\"500\" height=\"44\" rx=\"8\" class=\"box-write\" />\n              <text x=\"60\" y=\"173\" font-weight=\"600\">− Coupon discount</text>\n              <text x=\"530\" y=\"173\" text-anchor=\"end\" class=\"muted\">spread across lines, remainder on the last</text>\n\n              <path d=\"M290,190 L290,208\" stroke=\"currentColor\" fill=\"none\" marker-end=\"url(#arrow)\" />\n              <rect x=\"40\" y=\"212\" width=\"500\" height=\"40\" rx=\"8\" class=\"box-money\" />\n              <text x=\"60\" y=\"237\" font-weight=\"700\">= Net subtotal</text>\n              <text x=\"530\" y=\"237\" text-anchor=\"end\" class=\"muted\">the base every charge below is calculated on</text>\n\n              <path d=\"M290,252 L290,270\" stroke=\"currentColor\" fill=\"none\" marker-end=\"url(#arrow)\" />\n              <rect x=\"40\" y=\"274\" width=\"500\" height=\"44\" rx=\"8\" class=\"box-write\" />\n              <text x=\"60\" y=\"301\" font-weight=\"600\">+ Event charge rules</text>\n              <text x=\"530\" y=\"301\" text-anchor=\"end\" class=\"muted\">organizer's own fees — booking fee, service charge</text>\n\n              <path d=\"M290,318 L290,336\" stroke=\"currentColor\" fill=\"none\" marker-end=\"url(#arrow)\" />\n              <rect x=\"40\" y=\"340\" width=\"500\" height=\"44\" rx=\"8\" class=\"box-write\" />\n              <text x=\"60\" y=\"367\" font-weight=\"600\">+ Revenue plan (buyer-target)</text>\n              <text x=\"530\" y=\"367\" text-anchor=\"end\" class=\"muted\">the platform's cut, charged to the buyer</text>\n\n              <path d=\"M290,384 L290,398\" stroke=\"currentColor\" fill=\"none\" marker-end=\"url(#arrow)\" />\n              <rect x=\"40\" y=\"398\" width=\"500\" height=\"26\" rx=\"6\" class=\"box-money\" />\n              <text x=\"60\" y=\"416\" font-weight=\"600\">+ Processor fee</text>\n              <text x=\"530\" y=\"416\" text-anchor=\"end\" class=\"muted\">depends on the chosen payment method</text>\n\n              <rect x=\"580\" y=\"274\" width=\"290\" height=\"110\" rx=\"8\" class=\"box-auto\" />\n              <text x=\"725\" y=\"298\" text-anchor=\"middle\" font-weight=\"600\">Revenue plan (organizer-target)</text>\n              <text x=\"725\" y=\"320\" text-anchor=\"middle\" class=\"muted\">Snapshot only — no InvoiceItem.</text>\n              <text x=\"725\" y=\"338\" text-anchor=\"middle\" class=\"muted\">Never added to the buyer's total.</text>\n              <text x=\"725\" y=\"356\" text-anchor=\"middle\" class=\"muted\">Deducted from the organizer's</text>\n              <text x=\"725\" y=\"374\" text-anchor=\"middle\" class=\"muted\">payout at settlement.</text>\n              <path d=\"M540,362 L576,340\" stroke=\"currentColor\" fill=\"none\" stroke-dasharray=\"4 3\" marker-end=\"url(#arrow)\" />\n            </g>\n          </svg>\n        </div>\n\n        <h4>Where each number comes from</h4>\n        <div class=\"table-responsive\">\n          <table class=\"table table-sm table-bordered\">\n            <thead class=\"table-light\"><tr><th style=\"width:14rem\">Component</th><th style=\"width:22rem\">Source row and field</th><th>How it is calculated</th></tr></thead>\n            <tbody>\n              <tr>\n                <td><strong>Line price</strong></td>\n                <td><code>TicketPricePeriod.Amount</code> if a period applies, otherwise <code>TicketType.FullPrice</code></td>\n                <td><code>unitPrice × quantity</code>, rounded to 2 decimals.</td>\n              </tr>\n              <tr>\n                <td><strong>Membership discount</strong></td>\n                <td><code>SessionMembershipDiscount.DiscountType</code>, <code>.DiscountValue</code>, <code>.MaxDiscountAmount</code> — reached through <code>SessionMembershipType</code> for the member's active membership type</td>\n                <td>Percentage of the line total, or a fixed amount. Capped at <code>MaxDiscountAmount</code> and never more than the line itself. Applies only when the caller is a signed-in member with an <code>Active</code> membership.</td>\n              </tr>\n              <tr>\n                <td><strong>Coupon discount</strong></td>\n                <td><code>DiscountCoupon</code>, validated by <code>DiscountCouponService.ValidateCouponForEventAsync</code>; recorded on <code>EventInvoice.DiscountCouponId</code> and <code>.CouponDiscountAmount</code></td>\n                <td>Calculated against the total <em>after</em> the membership discount, then spread across lines in proportion to each line's net. The last line absorbs the rounding remainder so the parts always sum exactly.</td>\n              </tr>\n              <tr>\n                <td><strong>Event charge rule</strong></td>\n                <td><code>EventChargeRule</code> joined to <code>OrganizerChargeRule</code> — fields <code>.CalculationType</code>, <code>.Value</code>, <code>.Label</code>, <code>.ChargeKind</code></td>\n                <td><code>Fixed</code> uses the value as-is; <code>Percent</code> is <code>netSubtotal × value ÷ 100</code>. Only rules where <code>EventChargeRule.IsEnabled</code> and the underlying <code>OrganizerChargeRule.IsActive</code> are counted. Ordered by <code>DisplayOrder</code>.</td>\n              </tr>\n              <tr>\n                <td><strong>Revenue plan — buyer</strong></td>\n                <td><code>AdminFeePlanRule</code> where <code>RuleAppliesTo = Buyer</code>, resolved via <code>AdminRevenuePlanAssignment</code> for the organizer and the Event module</td>\n                <td>Same Fixed/Percent formula, on the same net subtotal. Becomes a visible charge line on the invoice.</td>\n              </tr>\n              <tr>\n                <td><strong>Revenue plan — organizer</strong></td>\n                <td><code>AdminFeePlanRule</code> where <code>RuleAppliesTo = Organizer</code></td>\n                <td>Same formula, but written only as a <code>PaymentChargeSnapshot</code> with no <code>InvoiceItem</code>. The buyer never sees it and it never touches <code>TotalAmount</code>.</td>\n              </tr>\n              <tr>\n                <td><strong>Processor fee</strong></td>\n                <td><code>OrganizerPaymentProcessorFee</code> matched on organizer, merchant and <code>PaymentProductId</code> — fields <code>.ValueType</code>, <code>.Value</code>, <code>.Label</code></td>\n                <td>Method-dependent, so it differs per payment method. A <strong>percentage</strong> is charged on <code>netSubtotal + all other buyer charges</code>; a <strong>fixed</strong> amount is calculated on <code>netSubtotal</code> alone. Quoted per method by <code>/price</code>, and only written to the invoice once a method is chosen at <code>/checkout/intent</code>.</td>\n              </tr>\n            </tbody>\n          </table>\n        </div>\n\n        <div class=\"plain\">\n          Every charge is written twice: as an <code>InvoiceItem</code> with\n          <code>ItemType = Charge</code>, which is what makes up the money owed, and as a\n          <code>PaymentChargeSnapshot</code>, which records <em>why</em> that amount was charged — the\n          rule, its value, its label and the currency, frozen at that moment. Editing the rule later\n          never changes an existing order.\n        </div>\n\n        <h4>What each payment method's total looks like</h4>\n        <p>\n          <code>/price</code> returns one <code>paymentBreakdowns</code> entry per method the event\n          offers, sorted cheapest first. They differ only in the processor fee:\n        </p>\n        <div class=\"table-responsive\">\n          <table class=\"table table-sm table-bordered\">\n            <thead class=\"table-light\"><tr><th style=\"width:12rem\">Method</th><th style=\"width:12rem\">Charge topology</th><th>Total</th></tr></thead>\n            <tbody>\n              <tr><td><strong>Card</strong></td><td>Direct charge on the connected account (<code>Stripe-Account</code> header sent)</td><td>net subtotal + charge rules + buyer revenue plan + the card processor fee</td></tr>\n              <tr><td><strong>ACH</strong> (US bank)</td><td>Destination charge on the platform account</td><td>Same, with the ACH processor fee — usually different from the card fee, which is why the totals differ per method</td></tr>\n              <tr><td><strong>PAD</strong> (Canadian bank)</td><td>Destination charge on the platform account</td><td>Same, with the PAD processor fee</td></tr>\n              <tr><td><strong>Cheque</strong></td><td>No Stripe involvement</td><td>Net subtotal + charge rules + buyer revenue plan. <strong>No processor fee at all</strong> — any fee left over from an earlier card attempt is cleared. Only visible to the event's own organizer.</td></tr>\n              <tr><td><strong>Free order</strong></td><td>No payment</td><td><code>TotalAmount</code> is zero, so there is no intent and no webhook. <code>/checkout/confirm</code> is the whole flow.</td></tr>\n            </tbody>\n          </table>\n        </div>\n\n        <h4>The application fee</h4>\n        <p>\n          Separate from all of the above, and easy to confuse with it. When the payment intent is\n          created, <code>CalculateApplicationFeeAsync</code> sums the <code>PaymentChargeSnapshot</code>\n          rows whose <code>SourceType</code> is <code>RevenuePlanRule</code> — both buyer-target and\n          organizer-target — and passes that as Stripe's <code>ApplicationFeeAmount</code>. That is the\n          platform's revenue, taken from the transaction.\n        </p>\n        <div class=\"rule\">\n          The organizer's own charge rules and the processor fee are <strong>never</strong> part of the\n          application fee. The processor fee exists to make the organizer whole for Stripe's cut;\n          handing it to the platform would take it twice. The figure is read from the persisted\n          snapshots, never recalculated.\n        </div>\n\n        <h4>Pricing is re-runnable</h4>\n        <p>\n          Calling <code>/price</code> twice must not double the charges, so it starts by calling\n          <code>ResetPricingAsync</code> to remove the previous run's charge lines and snapshots before\n          rebuilding them. Without that, the duplicate charge lines leave a balance the payment cannot\n          clear, the invoice lands on <code>PartiallyPaid</code>, and ticket issuance is then refused\n          on an order that was actually paid in full.\n        </p>"
  },
  {
    "id": "reg-questions",
    "title": "Attendees, questions and files",
    "html": "\n\n        <h4>When are attendee details required?</h4>\n        <div class=\"table-responsive\">\n          <table class=\"table table-sm table-bordered\">\n            <tbody>\n              <tr><th style=\"width:16rem\">The flag</th><td><code>Session.RequiresAttendeeInfo</code>, set by the organizer in the session wizard.</td></tr>\n              <tr><th>How the page knows</th><td><code>visibleTabs</code> contains <code>\"attendee-info\"</code> when <em>any</em> session in the event has the flag. <code>GET /register/attendee-info</code> then returns only those sessions.</td></tr>\n              <tr><th>What is stored</th><td>One <code>EventInvoiceItemAttendee</code> per seat, with a <code>SlotIndex</code>. Submitted per line, before payment.</td></tr>\n              <tr><th>The rule at submit</th><td>The number of attendees must equal the line quantity exactly, and each needs a name. Email and phone are optional.</td></tr>\n              <tr><th>What happens at issuance</th><td>Slot <em>n</em> becomes ticket <em>n</em>'s attendee. A submitted slot owns all its fields — a blank email means \"not provided\", it does <strong>not</strong> fall back to the buyer's. If no attendees were submitted at all, the tickets carry no attendee name.</td></tr>\n            </tbody>\n          </table>\n        </div>\n        <div class=\"dont\">\n          Attendee details are not enforced at payment time. Only the questionnaire is. If a session\n          requires attendee info, the frontend must collect it — the server will happily issue\n          nameless tickets otherwise.\n        </div>\n\n        <h4>When does the questionnaire appear?</h4>\n        <p>\n          Two independent sources, both authored by the organizer against the event:\n        </p>\n        <div class=\"table-responsive\">\n          <table class=\"table table-sm table-bordered\">\n            <thead class=\"table-light\"><tr><th style=\"width:14rem\">Source</th><th style=\"width:16rem\">Where it comes from</th><th>Answered by</th></tr></thead>\n            <tbody>\n              <tr>\n                <td><strong>Custom form</strong></td>\n                <td><code>EventForm</code> → <code>CustomForm</code> → <code>CustomFormField</code>. Forms are reusable and shared with Membership.</td>\n                <td><code>formResponses[]</code>, keyed by <code>fieldUniqueId</code>. Stored as <code>EventPurchaseSubmissionValue</code>.</td>\n              </tr>\n              <tr>\n                <td><strong>Custom question</strong></td>\n                <td><code>EventQuestion</code> with its <code>EventQuestionOption</code> rows, defined directly on the event.</td>\n                <td><code>questionResponses[]</code>, keyed by <code>questionUniqueId</code>. Stored as <code>EventQuestionResponse</code>.</td>\n              </tr>\n            </tbody>\n          </table>\n        </div>\n        <p>\n          The tab appears when the event has at least one active question, or at least one form that\n          actually contains a field. A form with no fields renders nothing, so it deliberately does not\n          put an empty tab in front of the buyer.\n        </p>\n        <div class=\"rule\">\n          Answers are <strong>per order, not per ticket</strong>. Ten tickets in one cart produce one\n          set of answers, because the organizer authored the questions against the event.\n        </div>\n\n        <h4>Where the requirement is enforced</h4>\n        <p>\n          Submitting answers is a separate call, so a caller could simply never make it.\n          <code>EventAnswerRequirement.EnsureRequiredAnswersPresentAsync</code> therefore runs at the\n          money, not at the answers — inside <code>/checkout/intent</code>,\n          <code>/checkout/cheque</code>, and inside <code>/checkout/confirm</code> for a zero-total\n          order. It refuses with the organizer's own <code>RequiredMessage</code> when one was written.\n        </p>\n        <p>\n          A mandatory field counts as answered when it has either a non-empty\n          <code>AnswerValue</code> or a <code>FileStorageId</code> — an uploaded file is an answer in\n          its own right.\n        </p>\n\n        <h4>Answer files, and why they are cleaned up</h4>\n        <p>\n          A file is uploaded the moment the buyer picks it, long before there is an answer to attach it\n          to. So the upload records an <code>EventAnswerFileUpload</code> row marking it in flight.\n        </p>\n        <ol class=\"step-rail\">\n          <li><strong>Upload.</strong> <code>UploadAnswerFileAsync</code> validates the extension against the field's <code>AcceptedFileTypes</code>, refuses executables whatever the organizer typed, saves the blob, and writes the in-flight row.</li>\n          <li><strong>Submit.</strong> <code>SubmitAnswersAsync</code> binds the <code>fileStorageId</code> to the answer and deletes the in-flight row — the file now belongs to an order.</li>\n          <li><strong>Sweep.</strong> Anything still marked in flight 24 hours later was abandoned. <code>EventAnswerFileCleanupService</code> deletes the blob and soft-deletes the <code>FileStorage</code> row, unless an answer claims it after all.</li>\n        </ol>\n        <p>\n          The 24-hour grace is far longer than any ticket hold, so a buyer still filling in the form\n          never loses their file. The frontend has nothing to do here — no delete call, no cleanup on\n          unload.\n        </p>"
  },
  {
    "id": "reg-settlement",
    "title": "Payment and settlement, step by step",
    "html": "\n\n        <div class=\"diagram\">\n          <svg viewBox=\"0 0 940 420\" role=\"img\" aria-label=\"Sequence from paying to tickets being emailed\">\n            <g font-size=\"12\" font-family=\"system-ui, sans-serif\">\n              <text x=\"90\" y=\"20\" text-anchor=\"middle\" font-weight=\"600\">Browser</text>\n              <text x=\"330\" y=\"20\" text-anchor=\"middle\" font-weight=\"600\">API</text>\n              <text x=\"570\" y=\"20\" text-anchor=\"middle\" font-weight=\"600\">Stripe</text>\n              <text x=\"820\" y=\"20\" text-anchor=\"middle\" font-weight=\"600\">Background jobs</text>\n              <line x1=\"90\" y1=\"30\" x2=\"90\" y2=\"400\" stroke=\"currentColor\" stroke-dasharray=\"3 4\" opacity=\".4\" />\n              <line x1=\"330\" y1=\"30\" x2=\"330\" y2=\"400\" stroke=\"currentColor\" stroke-dasharray=\"3 4\" opacity=\".4\" />\n              <line x1=\"570\" y1=\"30\" x2=\"570\" y2=\"400\" stroke=\"currentColor\" stroke-dasharray=\"3 4\" opacity=\".4\" />\n              <line x1=\"820\" y1=\"30\" x2=\"820\" y2=\"400\" stroke=\"currentColor\" stroke-dasharray=\"3 4\" opacity=\".4\" />\n\n              <path d=\"M90,56 L326,56\" stroke=\"currentColor\" fill=\"none\" marker-end=\"url(#arrow)\" />\n              <text x=\"208\" y=\"50\" text-anchor=\"middle\" class=\"muted\">POST /checkout/intent</text>\n\n              <path d=\"M330,86 L566,86\" stroke=\"currentColor\" fill=\"none\" marker-end=\"url(#arrow)\" />\n              <text x=\"448\" y=\"80\" text-anchor=\"middle\" class=\"muted\">create intent + application fee</text>\n\n              <path d=\"M566,116 L94,116\" stroke=\"currentColor\" fill=\"none\" marker-end=\"url(#arrow)\" />\n              <text x=\"330\" y=\"110\" text-anchor=\"middle\" class=\"muted\">clientSecret (via API; InvoicePayment = Pending)</text>\n\n              <path d=\"M90,150 L566,150\" stroke=\"currentColor\" fill=\"none\" marker-end=\"url(#arrow)\" />\n              <text x=\"328\" y=\"144\" text-anchor=\"middle\" class=\"muted\">buyer confirms the payment directly with Stripe</text>\n\n              <path d=\"M566,190 L334,190\" stroke=\"currentColor\" fill=\"none\" marker-end=\"url(#arrow)\" />\n              <text x=\"450\" y=\"184\" text-anchor=\"middle\" class=\"muted\">POST /api/public/stripe/web-hook</text>\n\n              <rect x=\"230\" y=\"204\" width=\"200\" height=\"72\" rx=\"8\" class=\"box-money\" />\n              <text x=\"330\" y=\"226\" text-anchor=\"middle\" font-weight=\"600\">Settlement</text>\n              <text x=\"330\" y=\"244\" text-anchor=\"middle\" class=\"muted\">invoice → Paid</text>\n              <text x=\"330\" y=\"262\" text-anchor=\"middle\" class=\"muted\">tickets issued, coupon spent</text>\n\n              <path d=\"M430,300 L816,300\" stroke=\"currentColor\" fill=\"none\" marker-end=\"url(#arrow)\" />\n              <text x=\"620\" y=\"294\" text-anchor=\"middle\" class=\"muted\">enqueue confirmation + ticket delivery</text>\n\n              <path d=\"M90,340 L326,340\" stroke=\"currentColor\" fill=\"none\" marker-end=\"url(#arrow)\" />\n              <text x=\"208\" y=\"334\" text-anchor=\"middle\" class=\"muted\">POST /checkout/confirm (fast path)</text>\n              <path d=\"M90,380 L326,380\" stroke=\"currentColor\" fill=\"none\" marker-end=\"url(#arrow)\" />\n              <text x=\"208\" y=\"374\" text-anchor=\"middle\" class=\"muted\">GET /orders/{id} — polled until Confirmed</text>\n            </g>\n          </svg>\n        </div>\n\n        <h4>What the webhook does, in order</h4>\n        <ol class=\"step-rail\">\n          <li><strong>Verifies the signature</strong> against the webhook secret from system settings. An unsigned or mismatched body is rejected.</li>\n          <li><strong>Reads the metadata</strong> on the payment intent. The intent was created carrying <code>ModuleId = Event</code> and <code>ModuleEntityUniqueId = the invoice's uniqueId</code>. Without that metadata the webhook returns success and does nothing — which is how other systems' intents are ignored.</li>\n          <li><strong>Settles the invoice</strong> through the shared invoice service: allocates the payment and moves the invoice to <code>Paid</code>.</li>\n          <li><strong>Routes to the module.</strong> For Event, <code>EventPaymentSettlementService.HandlePaymentSucceededAsync</code>.</li>\n          <li><strong>Records how it was paid</strong> — before the issuance gate, so even an order that ends up in recovery still has its payment source.</li>\n          <li><strong>Checks the issuance gate.</strong> If the invoice did not reach <code>Paid</code>, it logs loudly and queues the order for recovery rather than silently leaving a paid buyer with nothing.</li>\n          <li><strong>Issues tickets, one line at a time,</strong> each in its own transaction so one bad line cannot deny tickets to the rest of the order.</li>\n          <li><strong>Redeems the coupon</strong> — a coupon is only spent when an order actually settles.</li>\n          <li><strong>Queues the emails</strong> and returns. Never awaited: a slow handler makes Stripe time out and retry a payment that already succeeded.</li>\n        </ol>\n\n        <div class=\"plain\">\n          A redelivered webhook is safe. Issuance is idempotent — a line that already has its full set\n          of tickets returns the existing codes instead of minting new ones — and the handler\n          deliberately re-enters settlement on a repeat success event, because the first delivery may\n          have settled the invoice and then failed before issuing.\n        </div>\n\n        <h4>Why /checkout/confirm exists as well</h4>\n        <p>\n          Webhooks are not instant and, in a local or test environment, may never arrive at all.\n          <code>ConfirmCheckoutAsync</code> gives the buyer their tickets without waiting: it settles\n          any open attempt, re-reads the invoice, and if issuance is authorised runs exactly the same\n          issuance code. Whichever path arrives first wins; the other finds the work already done.\n        </p>\n        <p>\n          Issuance is authorised when <strong>any</strong> of these is true\n          (<code>TicketingShared.IsTicketIssuanceAuthorised</code>):\n        </p>\n        <ul>\n          <li>the invoice status is <code>Paid</code>;</li>\n          <li><code>TotalAmount</code> is zero or less — a free order;</li>\n          <li>a cheque payment exists that has not failed — and only an organizer-authenticated endpoint can record one.</li>\n        </ul>\n\n        <h4>What checkout refuses, and what each refusal means</h4>\n        <p>\n          None of these is a server error. Every one of them rolled its transaction back, so the buyer\n          was not charged and the call is safe to repeat. They arrive as an ordinary failed envelope —\n          <code>success: false</code> with a <code>message</code> written for the buyer to read.\n        </p>\n        <div class=\"table-responsive\">\n          <table class=\"table table-sm table-bordered\">\n            <thead class=\"table-light\"><tr><th style=\"width:22rem\">The message</th><th style=\"width:14rem\">Where it comes from</th><th>What the buyer should do</th></tr></thead>\n            <tbody>\n              <tr>\n                <td>\"Cheque payments are recorded through the cheque endpoint.\"</td>\n                <td><code>DescribeUnsupportedMethod</code> — a method this endpoint cannot start</td>\n                <td>Call <code>POST .../checkout/cheque</code> instead, signed in as the event's organizer. Checked <strong>before</strong> the seat claim, so nothing was held: a refusal decided by the method alone must not take seats out of circulation for a call that could never have succeeded.</td>\n              </tr>\n              <tr>\n                <td>\"Someone else is booking these tickets right now. Please try again.\"</td>\n                <td><code>TicketingShared.ConcurrencyRetryMessage</code> — the seat claim lost the row lock, or was chosen as the deadlock victim</td>\n                <td>Press pay again. Stock still exists on every line; the request simply queued behind another buyer and gave up after the 3-second cap.</td>\n              </tr>\n              <tr>\n                <td>\"'Early Bird' sold out before your payment could be taken. Your order was not charged.\"</td>\n                <td><code>DescribeSeatContentionAsync</code> — the same lost race, but the availability read afterwards found nothing left on that line</td>\n                <td>Nothing. Retrying cannot help. Send them back to the ticket picker.</td>\n              </tr>\n              <tr>\n                <td>The organizer's own message, or a validation sentence</td>\n                <td>Any <code>InvalidOperationException</code> raised inside the transaction — an expired hold, a missing required answer, a quantity no longer available</td>\n                <td>Fix what the sentence names, then price and pay again.</td>\n              </tr>\n              <tr>\n                <td>Stripe's decline message, quoted verbatim</td>\n                <td><code>DescribeStripeFailure</code> on a <code>card_error</code></td>\n                <td>Use a different card. Stripe writes these for cardholders, so the wording is already theirs.</td>\n              </tr>\n              <tr>\n                <td>\"Payments are busy right now. Please wait a moment and try again.\"</td>\n                <td><code>DescribeStripeFailure</code> on a <code>rate_limit_error</code> or HTTP 429 from Stripe</td>\n                <td>Wait a few seconds and press pay again — and note that <strong>the seats are still held</strong>, because the claim committed before Stripe was called. Do not send this buyer back to the ticket picker.</td>\n              </tr>\n              <tr>\n                <td>\"Payment could not be started. Please try again.\"</td>\n                <td>Any other <code>StripeException</code>, or a <code>DbUpdateException</code></td>\n                <td>Retry once. Stripe's own message is deliberately withheld here because it carries account, customer and request ids.</td>\n              </tr>\n            </tbody>\n          </table>\n        </div>\n        <div class=\"rule\">\n          The seat claim and the Stripe call are on opposite sides of a commit. A buyer refused by the\n          claim holds nothing; a buyer refused by Stripe holds their seats until the reservation expires\n          or <code>ReleaseAbandonedAttemptsAsync</code> clears the attempt on their next cart write. The\n          two refusals read alike and behave differently — do not collapse them into one handler.\n        </div>\n\n        <h4>When payment fails</h4>\n        <p>\n          <code>HandlePaymentFailedAsync</code> cancels every still-<code>Active</code> reservation on\n          the order and refreshes the ticket-type counters, putting the seats straight back on sale.\n          Tickets that were already issued are never revoked here — reversing a fulfilled order is a\n          refund, not a side-effect of a failed attempt.\n        </p>"
  },
  {
    "id": "reg-automatic",
    "title": "What runs without anybody asking",
    "html": "\n        <div class=\"table-responsive\">\n          <table class=\"table table-sm table-bordered\">\n            <thead class=\"table-light\"><tr><th style=\"width:16rem\">Job</th><th style=\"width:10rem\">Trigger</th><th>What it does</th></tr></thead>\n            <tbody>\n              <tr>\n                <td><code>EventTicketDeliveryJob.DeliverAsync</code></td>\n                <td>Queued at settlement</td>\n                <td>Renders each ticket with its QR code and emails it. Attendees with their own email address get their own ticket; the buyer always receives every ticket. Each send is recorded in <code>TicketDelivery</code>, so a resend knows what already went out. A QR that fails to render does not cost the buyer their ticket — the code is printed as text too.</td>\n              </tr>\n              <tr>\n                <td><code>EventRegistrationConfirmationDispatcher</code></td>\n                <td>Queued at settlement</td>\n                <td>Sends the organizer's own wizard-authored confirmation email. Held back if the order is incomplete, because a buyer about to be refunded must not first be told their place is confirmed.</td>\n              </tr>\n              <tr>\n                <td><code>EventCartMaintenanceHostedService</code></td>\n                <td>Every minute</td>\n                <td>Three isolated passes: expire stale reservations and return the seats, mark expired open carts <code>Abandoned</code>, then delete answer files that never became part of an order. A failure in one pass does not stop the others.</td>\n              </tr>\n              <tr>\n                <td><code>event-order-recovery-sweep</code></td>\n                <td>Every 10 minutes</td>\n                <td>Finds paid event orders with no tickets that the webhook never reported, retries issuance, and refunds the order if it cannot be fulfilled.</td>\n              </tr>\n              <tr>\n                <td><code>EventOrderRecoveryDispatcher</code></td>\n                <td>Queued at settlement, on failure</td>\n                <td>The same recovery, triggered immediately when settlement notices the order is short — either the gate refused or a line has no tickets.</td>\n              </tr>\n            </tbody>\n          </table>\n        </div>"
  },
  {
    "id": "reg-shapes",
    "title": "What comes back — every response, field by field",
    "html": "\n        <p>All of these arrive inside the standard envelope, in the <code>data</code> property.</p>\n\n        <h4><code>EventCartDto</code> — from create, add line, remove line, get cart</h4>\n        <div class=\"table-responsive\">\n          <table class=\"table table-sm table-bordered\">\n            <thead class=\"table-light\"><tr><th style=\"width:14rem\">Property</th><th style=\"width:8rem\">Type</th><th>Meaning</th></tr></thead>\n            <tbody>\n              <tr><td><code>cartUniqueId</code></td><td>guid</td><td>The cart's handle, and the buyer's only credential for it. Every later cart call needs it.</td></tr>\n              <tr><td><code>invoiceNo</code></td><td>string</td><td>Human-readable order number, generated by the database.</td></tr>\n              <tr><td><code>eventUniqueId</code></td><td>guid</td><td>Which event this cart belongs to.</td></tr>\n              <tr><td><code>expiresAtUtc</code></td><td>datetime?</td><td>When the seat hold lapses. Counted from cart creation, shared by every line. Show a countdown from this.</td></tr>\n              <tr><td><code>subTotal</code></td><td>decimal</td><td>Sum of the lines before any discount.</td></tr>\n              <tr><td><code>discountAmount</code></td><td>decimal?</td><td>Total discount applied so far. Null until the cart has been priced.</td></tr>\n              <tr><td><code>netSubtotal</code></td><td>decimal</td><td><code>subTotal − discountAmount</code>. The base every charge is calculated on.</td></tr>\n              <tr><td><code>totalAmount</code></td><td>decimal</td><td>What is owed. Equals the subtotal until <code>/price</code> has run — do not present it as a final total before then.</td></tr>\n              <tr><td><code>lines[]</code></td><td>array</td><td>The cart lines, below.</td></tr>\n            </tbody>\n          </table>\n        </div>\n\n        <h4><code>EventCartLineDto</code></h4>\n        <div class=\"table-responsive\">\n          <table class=\"table table-sm table-bordered\">\n            <thead class=\"table-light\"><tr><th style=\"width:14rem\">Property</th><th style=\"width:8rem\">Type</th><th>Meaning</th></tr></thead>\n            <tbody>\n              <tr><td><code>lineUniqueId</code></td><td>guid</td><td>The <code>EventInvoiceItem</code>'s id — this is what remove-line and submit-attendees expect, not the <code>InvoiceItem</code> id.</td></tr>\n              <tr><td><code>sessionUniqueId</code></td><td>guid</td><td>The session these seats are for.</td></tr>\n              <tr><td><code>ticketTypeUniqueId</code></td><td>guid</td><td>The ticket type bought.</td></tr>\n              <tr><td><code>ticketTypeName</code></td><td>string</td><td>Display name, for the cart summary.</td></tr>\n              <tr><td><code>quantity</code></td><td>int</td><td>Seats on this line. Also the exact number of attendees the attendee call will demand.</td></tr>\n              <tr><td><code>unitPrice</code></td><td>decimal</td><td>Price per seat, from the price period or the ticket type's full price.</td></tr>\n              <tr><td><code>lineTotal</code></td><td>decimal</td><td><code>unitPrice × quantity</code>.</td></tr>\n              <tr><td><code>discountAmount</code></td><td>decimal?</td><td>Membership and coupon discount landed on this line. Populated by <code>/price</code>.</td></tr>\n              <tr><td><code>reservationStatus</code></td><td>enum</td><td><code>Active</code> means the line still has a live reservation record. For cart reservations, stock is not consumed until <code>PaymentStartedUtc</code> is stamped during checkout.</td></tr>\n            </tbody>\n          </table>\n        </div>\n\n        <h4><code>EventCartPriceDto</code> — from <code>/price</code></h4>\n        <div class=\"table-responsive\">\n          <table class=\"table table-sm table-bordered\">\n            <thead class=\"table-light\"><tr><th style=\"width:16rem\">Property</th><th style=\"width:8rem\">Type</th><th>Meaning</th></tr></thead>\n            <tbody>\n              <tr><td><code>cartUniqueId</code></td><td>guid</td><td>Echoed back.</td></tr>\n              <tr><td><code>subTotal</code></td><td>decimal</td><td>Before discounts.</td></tr>\n              <tr><td><code>discountAmount</code></td><td>decimal</td><td>Membership plus coupon, combined.</td></tr>\n              <tr><td><code>netSubtotal</code></td><td>decimal</td><td>The base for every charge.</td></tr>\n              <tr><td><code>paymentBreakdowns[]</code></td><td>array</td><td>One entry per payment method the buyer may use, cheapest first.</td></tr>\n            </tbody>\n          </table>\n        </div>\n\n        <h4><code>EventCartPaymentBreakdownDto</code></h4>\n        <div class=\"table-responsive\">\n          <table class=\"table table-sm table-bordered\">\n            <thead class=\"table-light\"><tr><th style=\"width:16rem\">Property</th><th style=\"width:8rem\">Type</th><th>Meaning</th></tr></thead>\n            <tbody>\n              <tr><td><code>paymentMethod</code></td><td>string</td><td>The enum name — send this value back on <code>/checkout/intent</code>.</td></tr>\n              <tr><td><code>label</code></td><td>string</td><td>Human wording for the button.</td></tr>\n              <tr><td><code>isOrganizerOnly</code></td><td>bool</td><td>True for cheque. Only ever present when the caller is the event's own organizer.</td></tr>\n              <tr><td><code>merchantName</code></td><td>string?</td><td>Which gateway will process it.</td></tr>\n              <tr><td><code>subtotal</code></td><td>decimal</td><td>Net subtotal — identical across methods.</td></tr>\n              <tr><td><code>buyerChargeTotal</code></td><td>decimal</td><td>Every charge for this method, including its processor fee. This is what differs between methods.</td></tr>\n              <tr><td><code>grandTotal</code></td><td>decimal</td><td><code>subtotal + buyerChargeTotal</code>. The amount that will be charged.</td></tr>\n              <tr><td><code>charges[]</code></td><td>array</td><td>The itemised breakdown to display.</td></tr>\n            </tbody>\n          </table>\n        </div>\n\n        <h4><code>EventCartPaymentChargeDto</code></h4>\n        <div class=\"table-responsive\">\n          <table class=\"table table-sm table-bordered\">\n            <thead class=\"table-light\"><tr><th style=\"width:14rem\">Property</th><th style=\"width:8rem\">Type</th><th>Meaning</th></tr></thead>\n            <tbody>\n              <tr><td><code>source</code></td><td>string</td><td>Where the charge came from: <code>EventChargeRule</code>, <code>RevenuePlanRule</code> or <code>processor-fee</code>. Useful for grouping, not for display.</td></tr>\n              <tr><td><code>title</code></td><td>string</td><td>The label the organizer or platform gave it — show this.</td></tr>\n              <tr><td><code>valueType</code></td><td>string</td><td><code>Fixed</code> or <code>Percent</code>.</td></tr>\n              <tr><td><code>value</code></td><td>decimal</td><td>The rule's configured number: 2.50 for a fixed fee, 2.9 for 2.9%.</td></tr>\n              <tr><td><code>amount</code></td><td>decimal</td><td>What it actually works out to on this order. Sum of these equals <code>buyerChargeTotal</code>.</td></tr>\n            </tbody>\n          </table>\n        </div>\n\n        <h4><code>EventPaymentIntentResultDto</code> — from <code>/checkout/intent</code></h4>\n        <div class=\"table-responsive\">\n          <table class=\"table table-sm table-bordered\">\n            <thead class=\"table-light\"><tr><th style=\"width:16rem\">Property</th><th style=\"width:8rem\">Type</th><th>Meaning</th></tr></thead>\n            <tbody>\n              <tr><td><code>cartUniqueId</code></td><td>guid</td><td>Echoed back.</td></tr>\n              <tr><td><code>invoiceUniqueId</code></td><td>guid</td><td>The order id. Needed <em>before</em> confirming, because a redirecting payment method must be given a return URL that points at the order, not at the cart.</td></tr>\n              <tr><td><code>paymentIntentId</code></td><td>string</td><td>Stripe's id. Also stored as the <code>InvoicePayment.ReferenceNo</code> that settlement matches on.</td></tr>\n              <tr><td><code>clientSecret</code></td><td>string</td><td>What the browser confirms the payment with.</td></tr>\n              <tr><td><code>publishableKey</code></td><td>string</td><td>The key to initialise Stripe.js with.</td></tr>\n              <tr><td><code>stripeAccount</code></td><td>string?</td><td>Set for card and wallet payments, which are charged on the connected account and must be confirmed against it. <strong>Null for ACH and PAD</strong>, which settle on the platform account. Pass it to Stripe.js exactly as given — do not invent one when it is null.</td></tr>\n              <tr><td><code>paymentMethod</code></td><td>enum</td><td>Echoed back.</td></tr>\n              <tr><td><code>amount</code></td><td>decimal</td><td>The final charge, including the processor fee for this method.</td></tr>\n              <tr><td><code>currency</code></td><td>string</td><td>Stripe currency code.</td></tr>\n              <tr><td><code>processorFeeAmount</code></td><td>decimal</td><td>The fee that was just added for the chosen method, so the page can show what changed.</td></tr>\n              <tr><td><code>status</code></td><td>string?</td><td>Stripe's intent status at creation.</td></tr>\n            </tbody>\n          </table>\n        </div>\n\n        <h4><code>EventCheckoutConfirmationDto</code> — from <code>/checkout/confirm</code></h4>\n        <div class=\"table-responsive\">\n          <table class=\"table table-sm table-bordered\">\n            <thead class=\"table-light\"><tr><th style=\"width:16rem\">Property</th><th style=\"width:8rem\">Type</th><th>Meaning</th></tr></thead>\n            <tbody>\n              <tr><td><code>cartUniqueId</code></td><td>guid</td><td>Echoed back.</td></tr>\n              <tr><td><code>invoiceUniqueId</code></td><td>guid</td><td>The durable handle. The cart id dies with the cart; this is what survives to be polled, linked and quoted to support.</td></tr>\n              <tr><td><code>invoiceStatus</code></td><td>enum</td><td>The accounting status. Prefer <code>isSettled</code> for UI decisions.</td></tr>\n              <tr><td><code>isSettled</code></td><td>bool</td><td><strong>False is a normal answer, not an error</strong> — bank rails report \"processing\" for days. Send the buyer to the order page and let it poll.</td></tr>\n              <tr><td><code>lines[]</code></td><td>array</td><td>Per line, the issued ticket codes. Empty when nothing was issued yet.</td></tr>\n            </tbody>\n          </table>\n        </div>\n\n        <h4><code>EventChequePaymentResultDto</code> — from <code>/checkout/cheque</code></h4>\n        <div class=\"table-responsive\">\n          <table class=\"table table-sm table-bordered\">\n            <thead class=\"table-light\"><tr><th style=\"width:14rem\">Property</th><th style=\"width:8rem\">Type</th><th>Meaning</th></tr></thead>\n            <tbody>\n              <tr><td><code>cartUniqueId</code></td><td>guid</td><td>Echoed back.</td></tr>\n              <tr><td><code>invoiceNo</code></td><td>string</td><td>The order number to write on the cheque record.</td></tr>\n              <tr><td><code>amountDue</code></td><td>decimal</td><td>Still owing — a cheque does not settle the invoice.</td></tr>\n              <tr><td><code>ticketCodes[]</code></td><td>string[]</td><td>Issued immediately, even though the money has not arrived, so the organizer can register someone on the spot.</td></tr>\n            </tbody>\n          </table>\n        </div>\n\n        <h4><code>EventOrderStatusDto</code> — from <code>/orders/{id}</code></h4>\n        <div class=\"table-responsive\">\n          <table class=\"table table-sm table-bordered\">\n            <thead class=\"table-light\"><tr><th style=\"width:16rem\">Property</th><th style=\"width:8rem\">Type</th><th>Meaning</th></tr></thead>\n            <tbody>\n              <tr><td><code>orderUniqueId</code></td><td>guid</td><td>The order.</td></tr>\n              <tr><td><code>invoiceNo</code></td><td>string</td><td>Order number to show the buyer.</td></tr>\n              <tr><td><code>orderState</code></td><td>string</td><td><code>Confirmed</code>, <code>Processing</code> or <code>Failed</code>. Deliberately coarser than the invoice status — the buyer is owed one of three answers, not an eight-way accounting enum.</td></tr>\n              <tr><td><code>invoiceStatus</code></td><td>string</td><td>The underlying status, for support and debugging.</td></tr>\n              <tr><td><code>pollAfterSeconds</code></td><td>int</td><td>How long to wait before asking again. <strong>Zero means stop polling</strong> — the order is terminal. Obey this rather than choosing your own interval.</td></tr>\n              <tr><td><code>buyerName</code></td><td>string?</td><td>Who bought it.</td></tr>\n              <tr><td><code>buyerEmailMasked</code></td><td>string?</td><td>Masked past the first character. Anyone with the link reaches this page, so it may confirm where the tickets went without disclosing the address.</td></tr>\n              <tr><td><code>totalAmount</code> / <code>currencySymbol</code></td><td>decimal / string?</td><td>What was paid.</td></tr>\n              <tr><td><code>eventName</code>, <code>eventThemeColor</code>, <code>eventStartDateUtc</code>, <code>eventEndDateUtc</code></td><td>—</td><td>Enough to render a branded confirmation without a second call.</td></tr>\n              <tr><td><code>venueName</code>, <code>venueAddress</code>, <code>venueMapUrl</code></td><td>string?</td><td>Where to turn up.</td></tr>\n              <tr><td><code>tickets[]</code></td><td>array</td><td>Each with <code>ticketUniqueId</code>, <code>ticketCode</code>, <code>ticketTypeName</code>, <code>sessionName</code>, <code>sessionStartDateUtc</code>, <code>attendeeName</code> and <code>ticketStatus</code>. Empty while the order is still processing.</td></tr>\n            </tbody>\n          </table>\n        </div>\n\n        <h4><code>UploadAnswerFileResponse</code> — from <code>/answers/files</code></h4>\n        <div class=\"table-responsive\">\n          <table class=\"table table-sm table-bordered\">\n            <tbody>\n              <tr><th style=\"width:14rem\"><code>fileStorageId</code></th><td>int — the id to send back in <code>formResponses[].fileStorageId</code> or <code>questionResponses[].fileStorageId</code>. On its own it is not an answer yet.</td></tr>\n              <tr><th><code>fileName</code></th><td>string — the stored file's name, to display next to the field.</td></tr>\n            </tbody>\n          </table>\n        </div>\n\n        <h4><code>EventRegistrationResponse</code> — from every <code>/register/*</code> call</h4>\n        <p>\n          One class serves all six registration reads; each endpoint fills the parts its tab needs and\n          leaves the rest empty. The fields that drive behaviour rather than display:\n        </p>\n        <div class=\"table-responsive\">\n          <table class=\"table table-sm table-bordered\">\n            <thead class=\"table-light\"><tr><th style=\"width:18rem\">Property</th><th>Meaning</th></tr></thead>\n            <tbody>\n              <tr><td><code>registrationStatus</code> / <code>canRegister</code> / <code>registrationBlockedReason</code></td><td>Whether the buyer may proceed, and if not, why — before the sale window opens, after it closes, event cancelled.</td></tr>\n              <tr><td><code>visibleTabs[]</code></td><td>Which steps this event actually has: <code>description</code>, <code>sessions</code>, <code>attendee-info</code>, <code>questionnaire</code>, <code>payment</code>. Build the wizard from this rather than assuming a fixed set.</td></tr>\n              <tr><td><code>purchaseTimeLimitMinutes</code> / <code>purchaseTimeLimitExpiresAtUtc</code></td><td>The hold duration for this event, so the countdown can be shown before a cart even exists.</td></tr>\n              <tr><td><code>isOrganizer</code></td><td>True when the caller owns the event. Cheque only appears in that case.</td></tr>\n              <tr><td><code>acceptsDiscountCoupons</code></td><td>Whether a redeemable coupon exists right now. Hides the coupon field when none does — and deliberately carries no codes: the page needs to know one exists, never which.</td></tr>\n              <tr><td><code>paymentAccountUniqueId</code> / <code>paymentAccountCurrency</code></td><td>What to pass to the Stripe credentials call, and which currency to format in.</td></tr>\n              <tr><td><code>sessions[]</code></td><td>Sessions with their ticket types. Each carries <code>requiresAttendeeInfo</code>.</td></tr>\n              <tr><td><code>forms[]</code> / <code>questions[]</code></td><td>The questionnaire definitions to render.</td></tr>\n              <tr><td><code>paymentMethods[]</code> / <code>paymentBreakdowns[]</code></td><td>Legacy preview of methods and totals. Prefer <code>/cart/{id}/price</code>, which prices the real cart.</td></tr>\n            </tbody>\n          </table>\n        </div>"
  },
  {
    "id": "reg-traps",
    "title": "Registration-specific traps",
    "html": "\n        <div class=\"table-responsive\">\n          <table class=\"table table-sm table-bordered\">\n            <thead class=\"table-light\"><tr><th style=\"width:22rem\">The trap</th><th>What actually happens</th></tr></thead>\n            <tbody>\n              <tr><td><strong>Showing a total without calling <code>/price</code></strong></td><td>The cart's <code>totalAmount</code> is only the subtotal until pricing runs. No charges, no processor fee.</td></tr>\n              <tr><td><strong>Caching the total across a cart edit</strong></td><td>Add or remove a line and the charge lines are wiped. The stale total will not match what the intent charges.</td></tr>\n              <tr><td><strong>Using the same total for every payment method</strong></td><td>Processor fees differ per method. That is the entire reason <code>/price</code> returns an array.</td></tr>\n              <tr><td><strong>Sending <code>stripeAccount</code> when it came back null</strong></td><td>ACH and PAD live on the platform account. Confirming against a connected account fails.</td></tr>\n              <tr><td><strong>Treating <code>isSettled: false</code> as a failure</strong></td><td>Bank payments are legitimately pending for days. Send the buyer to the order page.</td></tr>\n              <tr><td><strong>Polling the order page on your own timer</strong></td><td><code>pollAfterSeconds</code> reaching zero is the stop signal, and the endpoint is rate-limited to 60 per minute per IP.</td></tr>\n              <tr><td><strong>Passing the <code>InvoiceItem</code> id as the line id</strong></td><td>Routes expect the <code>EventInvoiceItem</code>'s <code>uniqueId</code> — the <code>lineUniqueId</code> the cart returned.</td></tr>\n              <tr><td><strong>Submitting fewer attendees than the line quantity</strong></td><td>Refused outright. It must be exact.</td></tr>\n              <tr><td><strong>Skipping the answers call</strong></td><td>It is not enforced at the answers endpoint — it is enforced at payment, where the buyer is refused with the organizer's own message.</td></tr>\n              <tr><td><strong>Refunding because a ticket email failed</strong></td><td>The order is intact. Use the organizer's resend endpoint.</td></tr>\n              <tr><td><strong>Sending a cheque to <code>/checkout/intent</code></strong></td><td>That route only starts Stripe payments. Cheque has its own organizer-authenticated endpoint, and one call there records the payment and issues the tickets — no intent, no confirm, no Payment Element.</td></tr>\n              <tr><td><strong>Showing a cheque order as fully paid</strong></td><td>The tickets are issued while the invoice stays owing. <code>amountDue</code> comes back non-zero on purpose and has to be shown.</td></tr>\n              <tr><td><strong>Treating a refusal as a server error</strong></td><td>Every refusal at <code>/checkout/intent</code> comes back as a normal failed envelope with a buyer-readable message. A 5xx from that route is a defect, not a busy ticket type.</td></tr>\n              <tr><td><strong>Sending a throttled buyer back to the ticket picker</strong></td><td>\"Payments are busy right now\" means Stripe refused after the seats were already claimed. The buyer still holds them; retrying payment is the whole fix.</td></tr>\n              <tr><td><strong>Retrying \"sold out before your payment could be taken\"</strong></td><td>That wording is only chosen once availability has been re-read and found empty. Retrying cannot succeed.</td></tr>\n              <tr><td><strong>Expecting a shared <code>Invoice</code> while the cart is open</strong></td><td>An open cart is an <code>EventInvoice</code> only. The shared invoice and its order number are minted at <code>/checkout/intent</code>, so <code>orderNumber</code> is null until payment starts.</td></tr>\n              <tr><td><strong>Pointing Stripe at <code>/webhooks/stripe</code></strong></td><td>That route only logs. The real one is <code>/api/public/stripe/web-hook</code>.</td></tr>\n              <tr><td><strong>Deploying without <code>EventCartCapability:SigningKey</code></strong></td><td>The API does not start. There is no default key on purpose &mdash; see <a href=\"#reg-cart-capability\">\"Who is allowed to touch a cart\"</a>.</td></tr>\n              <tr><td><strong>Treating the cart id as proof of ownership</strong></td><td>It never was. The capability cookie is the credential; a cart id passed to another browser, device or email link opens nothing.</td></tr>\n              <tr><td><strong>Reading <code>403 cart_capability_required</code> as \"cart not found\"</strong></td><td>It says nothing about existence, deliberately. Send the buyer back to the event page to start again; do not retry.</td></tr>\n            </tbody>\n          </table>\n        </div>"
  }
]
